import {generateDocument, applyColors} from './generators.js';
const $ = id => document.getElementById(id);
const defaults = ['#db9279','#458b88','#efc56f','#596d9c','#aa77a8','#829959','#ce6676','#77a9c4','#a88360','#b4a154'];
const API = location.hostname === '127.0.0.1' || location.hostname === 'localhost' ? '' : 'http://127.0.0.1:5174';
let colors = [...defaults, ...defaults], rendered = null, connected = false, engine = null, busy = false, zoom = 1, revision = 0, rerenderTimer;
const settings = () => ({m:Number($('m').value),n:Number($('n').value),hand:document.querySelector('[name=hand]:checked').value,stretch:$('stretch').checked,continuation:false,k:Number($('k').value),colors:colors.slice(0,Number($('m').value)+Number($('n').value)),animals:engine!=='browser'&&$('animals').checked,names:engine!=='browser'&&$('names').checked,emojiSet:$('emoji-set').value,transparent:true,scale:1});
const same = (a,b) => JSON.stringify(a) === JSON.stringify(b);
function status(message,error=false) {$('result-status').textContent=message;$('result-status').classList.toggle('error',error);}
function current() {return rendered && same(rendered.request, settings());}
function syncButtons() {$('generate').disabled=!connected||busy;$('export-json').disabled=!current()||busy;$('export-image').disabled=!current()||busy;}
async function request(path, body) {
  const response=await fetch(API+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(body?120000:5000)});
  const data=await response.json();if(!response.ok)throw Error(data.error||'The renderer returned an error.');return data;
}
// Without the local renderer, starting stitches are generated by generators.js and
// drawn by the vendored OpenStrandJS renderer (vendor/strand-renderer.js).
function renderInBrowser(s) {
  const document=applyColors(generateDocument(s.m,s.n,s.hand,s.stretch),s.colors);
  const state=document.states.find(x=>x.step===document.current_step);
  const strands=structuredClone(state.data.strands);
  // Bounds as in RenderMixin._calculate_strands_bounds: every endpoint and control point, padded by 100.
  const points=strands.flatMap(x=>[x.start,x.end,...(x.control_points||[])]).filter(Boolean);
  const pad=100,minX=Math.min(...points.map(p=>p.x))-pad,minY=Math.min(...points.map(p=>p.y))-pad;
  const width=Math.ceil(Math.max(...points.map(p=>p.x))+pad-minX),height=Math.ceil(Math.max(...points.map(p=>p.y))+pad-minY);
  if(width*height*s.scale**2>36_000_000)throw Error('Image is too large at this resolution. Choose a lower scale.');
  const canvas=window.document.createElement('canvas');
  window.renderFixture(strands,{image_width:width*s.scale,image_height:height*s.scale,x_offset:-minX*s.scale,y_offset:-minY*s.scale,supersample:2,zoom:s.scale,shadow_enabled:false,shadow_overrides:state.data.shadow_overrides,canvas_bg:s.transparent?'transparent':'white'},canvas);
  const all=state.data.strands;
  return {png:canvas.toDataURL('image/png').split(',')[1],document,width:canvas.width,height:canvas.height,
    strands:all.filter(x=>x.type!=='MaskedStrand').length,crossings:all.filter(x=>x.type==='MaskedStrand').length,settings:s};
}
const render=s=>engine==='native'?request('/api/render',s):Promise.resolve().then(()=>renderInBrowser(s));
function useEngine(name){engine=name;connected=true;const browser=name==='browser';
  for(const id of ['animals','names'])$(id).disabled=browser;$('emoji-set').disabled=browser||!$('animals').checked;
  $('browser-note').hidden=!browser;$('connection-note').hidden=true;
  $('engine-status').textContent=browser?'Rendering in your browser with OpenStrandJS':'OpenStrandStudio connected · native Qt rendering';}
async function connect() {
  $('connect').disabled=true;$('engine-status').textContent='Looking for the local OpenStrandStudio renderer…';
  try {const health=await request('/api/health');if(health.renderer!=='OpenStrandStudio')throw Error('Unexpected renderer');const switched=engine!=='native';useEngine('native');syncButtons();if(!rendered||switched)await generate();}
  catch(e){const switched=engine!=='browser';useEngine('browser');syncButtons();if(!rendered||switched)await generate();}
  finally {$('connect').disabled=false;syncButtons();}
}
function palette(){const s=settings();if(!Number.isInteger(s.m+s.n)||s.m<1||s.n<1||s.m>10||s.n>10)return;$('set-count').textContent=`${s.m+s.n} sets`;$('colors').replaceChildren();for(let i=0;i<s.m+s.n;i++){const label=document.createElement('label');label.className='color-field';const input=document.createElement('input');input.type='color';input.value=colors[i];input.setAttribute('aria-label',`Set ${i+1} color`);const text=document.createElement('span');text.innerHTML=`Set ${i+1} · ${i<s.n?'H':'V'}<small>${colors[i].toUpperCase()}</small>`;input.addEventListener('input',()=>{colors[i]=input.value;text.querySelector('small').textContent=input.value.toUpperCase();changed(true);});label.append(input,text);$('colors').append(label);}}
function changed(automatic=false){revision++;syncButtons();if(!current())status('Settings changed · Generate to update the canvas');if(automatic&&connected){clearTimeout(rerenderTimer);rerenderTimer=setTimeout(()=>generate(),250);}}
for(const id of ['m','n','stretch'])$(id).addEventListener('input',()=>{palette();changed();});
$('k').addEventListener('input',()=>changed(true));
document.querySelectorAll('[name=hand]').forEach(el=>el.addEventListener('change',()=>changed(true)));
for(const id of ['animals','names','emoji-set'])$(id).addEventListener('change',()=>{$('emoji-set').disabled=!$('animals').checked;changed(true);});
$('random').onclick=()=>{colors=colors.map(()=>`#${Array.from({length:3},()=>Math.floor(65+Math.random()*160).toString(16).padStart(2,'0')).join('')}`);palette();changed(true);};
$('reset-colors').onclick=()=>{colors=[...defaults,...defaults];palette();changed(true);};
async function generate(navigate=false){
  if(!$('settings').reportValidity()||!connected)return;
  if(busy){clearTimeout(rerenderTimer);rerenderTimer=setTimeout(()=>generate(navigate),250);return;}
  const submitted=settings(),thisRevision=revision;busy=true;syncButtons();$('generate').textContent='Rendering…';status(engine==='native'?'Drawing native strand layers…':'Drawing strand layers with OpenStrandJS…');
  try{const data=await render(submitted);const image=new Image();image.src=`data:image/png;base64,${data.png}`;image.alt=`${submitted.m} by ${submitted.n} ${submitted.hand==='lh'?'left':'right'}-hand pattern, rendered by ${engine==='native'?'OpenStrandStudio':'OpenStrandJS'}${submitted.animals?', with PNG animal markers':''}`;await image.decode();if(thisRevision!==revision){status('Settings changed · Waiting for the latest preview');return;}rendered={...data,request:submitted};$('preview').replaceChildren(image);zoom=1;updateZoom();$('pattern-title').textContent=`${submitted.m} × ${submitted.n} / ${submitted.hand==='lh'?'Left-hand':'Right-hand'}`;$('variant-label').textContent=submitted.continuation?'CONTINUATION':submitted.stretch?'STRETCHED':'STANDARD';status(thisRevision===revision?`${data.strands} strands · ${data.crossings} crossings · k=${submitted.k>=0?"+":""}${submitted.k} · ${submitted.hand==='lh'?'CW':'CCW'}`:'Settings changed · Generate to update the canvas');if(navigate){if(engine==='native')await window.openContinuation(data);else status(`${$('result-status').textContent} · Continuation needs the local renderer: start it, then click Reconnect renderer`);}}
  catch(e){status(`Render failed: ${e.message}`,true);}
  finally{busy=false;$('generate').innerHTML='Generate starting stitch <span>→</span>';syncButtons();}
}
$('settings').onsubmit=e=>{e.preventDefault();generate(true);};$('connect').onclick=connect;
function updateZoom(){const image=$('preview').querySelector('img');if(image)image.style.transform=`scale(${zoom})`;$('fit').textContent=`${Math.round(zoom*100)}%`;}
$('zoom-in').onclick=()=>{zoom=Math.min(3,zoom+.25);updateZoom();};$('zoom-out').onclick=()=>{zoom=Math.max(.25,zoom-.25);updateZoom();};$('fit').onclick=()=>{zoom=1;updateZoom();};
function download(blob,extension,s){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`mxn-${s.m}x${s.n}-${s.hand}${s.continuation?'-continuation':s.stretch?'-stretch':''}${s.animals?'-animals':''}.${extension}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('export-json').onclick=()=>{if(current())download(new Blob([JSON.stringify(rendered.document,null,2)],{type:'application/json'}),'json',rendered.request);};
$('export-image').onclick=()=>$('export-dialog').showModal();$('help').onclick=()=>$('about-dialog').showModal();
$('download').onclick=async()=>{if(!current()||busy)return;busy=true;syncButtons();$('download').disabled=true;$('download').textContent='Rendering PNG…';const s={...rendered.request,scale:Number($('scale').value),transparent:$('transparent').checked};
  try{const data=same(s,rendered.request)?rendered:await render(s);const bytes=Uint8Array.from(atob(data.png),x=>x.charCodeAt(0));download(new Blob([bytes],{type:'image/png'}),'png',s);$('export-dialog').close();status(engine==='native'?'Native PNG downloaded':'PNG downloaded');}
  catch(e){status(`Export failed: ${e.message}`,true);$('export-dialog').close();}
  finally{busy=false;$('download').disabled=false;$('download').textContent='Download PNG ↓';syncButtons();}
};
palette();syncButtons();connect();
